        or not Public(sender) or type(sender) ~= "string" or #sender == 0 or #sender > 128
        or not Public(localID) or type(localID) ~= "number"
        or not Public(name) or type(name) ~= "string" or #name ~= #SHARED_CHANNEL then return end
