end--[[APR_DIAG]]; APR.versionCheck.HandleSharedMessage = APRTrace("APR-Core/core/VersionCheck.lua:245:APR.versionCheck:HandleSharedMessage#20", APR.versionCheck.HandleSharedMessage)--[[/APR_DIAG]]

function APR.versionCheck:OnDisable()
    self:StopBroadcasts()
    self:StopSharedChannel()
end--[[APR_DIAG]]; APR.versionCheck.OnDisable = APRTrace("APR-Core/core/VersionCheck.lua:293:APR.versionCheck:OnDisable#22", APR.versionCheck.OnDisable)--[[/APR_DIAG]]

function APR.versionCheck:RefreshSettings()
    if SharedEnabled() then
        self:CheckKnownVersion()
        self:StartSharedChannel()
    else
        self:StopSharedChannel()
        self:StopBroadcasts()
    end
end--[[APR_DIAG]]; APR.versionCheck.RefreshSettings = APRTrace("APR-Core/core/VersionCheck.lua:298:APR.versionCheck:RefreshSettings#23", APR.versionCheck.RefreshSettings)--[[/APR_DIAG]]

function APR.versionCheck:OnInit()
    self:RememberVersion(APR.version)
    self:CheckKnownVersion()
    self:CheckInterfaceVersion()
    self:StartSharedChannel()
end--[[APR_DIAG]]; APR.versionCheck.OnInit = APRTrace("APR-Core/core/VersionCheck.lua:308:APR.versionCheck:OnInit#24", APR.versionCheck.OnInit)--[[/APR_DIAG]]
